const item = $input.item.json.body || $input.item.json;
const score = item.test_score || 0;
const passingScore = item.passing_score || 80;
const isSelected = score >= passingScore;

return [{
  json: {
    candidate_id: item.candidate_id || '',
    candidate_email: item.candidate_email || '',
    candidate_name: item.candidate_name || 'Candidate',
    job_id: item.job_id || 'python-ml-developer-001',
    test_score: score,
    passing_score: passingScore,
    is_selected: isSelected,
    total_questions: item.total_questions || 10,
    correct_answers: item.correct_answers || 0
  }
}];
